import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0025 (Archived): HTTP Client/Server v1 — Complete","description":"","frontmatter":{"title":"ADR-0025 (Archived): HTTP Client/Server v1 — Complete","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"web/project/adrs/archived/0025-http-server-v1-complete.md","filePath":"vendored/web/project/adrs/archived/0025-http-server-v1-complete.md"}`),a={name:`web/project/adrs/archived/0025-http-server-v1-complete.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0025-archived-http-client-server-v1-—-complete" tabindex="-1">ADR-0025 (Archived): HTTP Client/Server v1 — Complete <a class="header-anchor" href="#adr-0025-archived-http-client-server-v1-—-complete" aria-label="Permalink to “ADR-0025 (Archived): HTTP Client/Server v1 — Complete”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The handl runtime needed HTTP capabilities for both clients and servers. The initial implementation had only a client, with a unified name that didn&#39;t reflect server capabilities. The async module system also needed to be extended to support <code>AsyncFunction</code> and <code>Operation</code> dispatch.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Completed v1 of HTTP client/server support:</p><h3 id="_1-renamed-http-client-crates" tabindex="-1">1. Renamed HTTP client crates <a class="header-anchor" href="#_1-renamed-http-client-crates" aria-label="Permalink to “1. Renamed HTTP client crates”">​</a></h3><ul><li><code>lib-http</code> → <code>lib-http-client</code></li><li><code>lib-http-std</code> → <code>lib-http-client-std</code></li><li>Preserved all public API names and <code>ureq</code> implementation</li></ul><h3 id="_2-extended-module-async-operation-dispatch" tabindex="-1">2. Extended module async/operation dispatch <a class="header-anchor" href="#_2-extended-module-async-operation-dispatch" aria-label="Permalink to “2. Extended module async/operation dispatch”">​</a></h3><ul><li>Added <code>Module::async_function</code> and <code>Module::operation</code> default methods</li><li>Updated <code>ModuleHost</code> to forward async and operation calls</li><li>Tested with unit tests in <code>runtime-core</code></li></ul><h3 id="_3-introduced-handl-lib-http-server-abstract" tabindex="-1">3. Introduced <code>handl-lib-http-server</code> (abstract) <a class="header-anchor" href="#_3-introduced-handl-lib-http-server-abstract" aria-label="Permalink to “3. Introduced handl-lib-http-server (abstract)”">​</a></h3><ul><li>Defined <code>HttpServer</code> trait with <code>start</code>, <code>stop</code>, <code>join</code>, <code>route</code>, <code>serve_static</code>, <code>is_running</code></li><li>Defined <code>HttpServerRequest</code>, <code>HttpServerResponse</code>, <code>HttpServerError</code> types</li><li>Created <code>HttpServerModule</code> exposing <code>http_server.*</code> functions</li><li>Added <code>StubHttpServer</code> for testing</li></ul><h3 id="_4-introduced-handl-lib-http-server-std-concrete" tabindex="-1">4. Introduced <code>handl-lib-http-server-std</code> (concrete) <a class="header-anchor" href="#_4-introduced-handl-lib-http-server-std-concrete" aria-label="Permalink to “4. Introduced handl-lib-http-server-std (concrete)”">​</a></h3><ul><li>Implemented <code>StdHttpServer</code> using <code>tokio</code> + <code>hyper</code> 1.x</li><li>HTTP/1.1 and HTTP/2 keep-alive support (via hyper features)</li><li>Multi-threaded Tokio runtime</li><li>Trie-based routing with <code>matchit</code> for static and named parameter segments</li><li>Graceful shutdown</li><li>Per-request body size limit and timeout</li><li>Static file serving with path-sanitization and MIME guessing</li></ul><h3 id="_5-updated-workspace" tabindex="-1">5. Updated workspace <a class="header-anchor" href="#_5-updated-workspace" aria-label="Permalink to “5. Updated workspace”">​</a></h3><ul><li>Added four new crate members to <code>Cargo.toml</code></li><li>Added workspace dependency entries and feature flags</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><ul><li>✅ Client crates renamed and working</li><li>✅ Module async/operation dispatch implemented</li><li>✅ Abstract server interface defined and tested</li><li>✅ Concrete server implementation with HTTP/1.1 + HTTP/2, routing, static files</li><li>✅ Workspace integration passing tests</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>handl has both HTTP client and server capabilities as first-class features</li><li>The module system supports async and operation patterns for extensibility</li><li>HTTP/2 support is available (via hyper) for high-performance connections</li><li>Path parameter routing is available (via matchit) for dynamic routes</li><li>Production-grade baseline server ready for further enhancements</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See also”">​</a></h2><ul><li>ADR-0025 (Remaining) for v1.x and v2 enhancements</li><li>Crates: <code>plugin-lib-http-client</code>, <code>plugin-lib-http-client-std</code>, <code>plugin-lib-http-server</code>, <code>plugin-lib-http-server-std</code></li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};